pug:
table.row.cta-banner(role='presentation')
    tr
        td.banner-cell(align='center')
            h2.banner-title {{ title }}
            p.banner-sub {{ subtitle }}
            table.cta(role='presentation' align='center')
                tr
                    td.butt
                        a.butt-link(href='{{ cta_href }}' target='_blank') {{ cta_label }}

styl:
.row.cta-banner td.banner-cell { background-color: {{ bg_color }}; padding: 40px 32px; text-align: center; border-radius: {{ radius }}px; }
.row.cta-banner h2.banner-title { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 26px; line-height: 1.25; color: {{ title_color }}; margin: 0 0 12px; padding: 0; }
.row.cta-banner p.banner-sub { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: 15px; line-height: 1.5; color: {{ subtitle_color }}; margin: 0 0 24px; padding: 0; }
.row.cta-banner td.butt { background-color: {{ button_bg }}; border-radius: {{ button_radius }}px; padding: 0; }
.row.cta-banner a.butt-link { display: block; padding: 14px 32px; font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 16px; color: {{ button_text_color }}; text-decoration: none; }
